package db

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"

	"github.com/google/uuid"
)

// A staged deletion is rolled back when its record survived the transaction.
// Final IPAs without a published row can be left by a crash between rename
// and commit; only names generated by this application are eligible for removal.
func (d *Db) recoverPackages(ctx context.Context) error {
	entries, err := os.ReadDir(filepath.Join(d.dir, "packages"))
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		staged := strings.HasSuffix(name, ".ipa.delete")
		base := strings.TrimSuffix(name, ".delete")
		id, ok := strings.CutSuffix(base, ".ipa")
		if !ok || !validPackageId(id) {
			continue
		}
		published, err := exists(ctx, d.conn, "SELECT 1 FROM packages WHERE id=? AND size IS NOT NULL", id)
		if err != nil {
			return err
		}
		path := filepath.Join(d.dir, "packages", name)
		if staged && published {
			err = os.Rename(path, d.PackagePath(id))
		} else if staged || !published {
			err = os.Remove(path)
		}
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
	}
	return nil
}

func validPackageId(id string) bool {
	parsed, err := uuid.Parse(id)
	return err == nil && parsed.String() == id
}
